// Jittered exponential backoff, never longer than the client's maxRetryDelay.
function retryBackoff(client, attempt) {
  return Math.min(client.maxRetryDelay, 60000, 500 * (2 ** attempt)) * (0.5 + client._random() * 0.5);
}

// A retry is attempted only when the server's own wait fits maxRetryDelay and
// the wait keeps the whole call inside the optional retryBudget.
function retryWaitAllowed(client, wait, serverWait, startedAt) {
  if (serverWait !== undefined && serverWait > client.maxRetryDelay) return false;
  return client.retryBudget === undefined || Date.now() - startedAt + wait <= client.retryBudget;
}

const RESERVED = /%3A|%2F|%3F|%23|%5B|%5D|%40|%21|%24|%26|%27|%28|%29|%2A|%2B|%2C|%3B|%3D/gi;

function encodePart(value, allowReserved = false) {
  const encoded = encodeURIComponent(String(value));
  return allowReserved
    ? encoded.replace(RESERVED, (match) => decodeURIComponent(match))
    : encoded;
}

function entriesOf(value) {
  return value && typeof value === "object" && !Array.isArray(value)
    ? Object.entries(value)
    : [];
}

function selectResponseProtocol(request, operation) {
  const descriptor = RESPONSE_DESCRIPTORS[operation];
  if (request.binaryStream !== undefined && typeof request.binaryStream !== "boolean") {
    throw new TypeError(`binaryStream must be a boolean for ${operation}`);
  }
  if (request.binaryStream === true) {
    if (request.maxResponseBytes !== undefined && !(typeof request.maxResponseBytes === "number" && Number.isSafeInteger(request.maxResponseBytes) && request.maxResponseBytes > 0)) {
      throw new TypeError("maxResponseBytes must be a positive integer number of bytes");
    }
    if (request.rawResponse === true || request.responseProtocol !== undefined || request.streamResponse !== undefined || request._rawStream) {
      throw new TypeError(`Conflicting binary stream options for ${operation}`);
    }
    const mediaTypes = [...new Set(Object.values((descriptor && descriptor.responses) || {})
      .filter(response => response.success)
      .flatMap(response => response.contentTypes || [])
      .map(media => media.split(";", 1)[0].trim().toLowerCase())
      .filter(media => media !== "application/json" && !(media.startsWith("application/") && media.endsWith("+json"))
        && !["text/event-stream", "application/x-ndjson", "application/ndjson", "application/jsonl", "application/x-jsonlines"].includes(media)))].sort();
    if (!mediaTypes.length) throw new TypeError(`Binary streaming is not declared for ${operation}`);
    return { protocol: "binary", mediaTypes, accept: mediaTypes.join(", ") };
  }
  const protocols = descriptor && descriptor.responseProtocols;
  if (!protocols) {
    if (request.responseProtocol !== undefined) {
      throw new TypeError(`Response protocol selection is not declared for ${operation}`);
    }
    return undefined;
  }
  const explicit = request.responseProtocol;
  const legacy = request.streamResponse;
  if (legacy !== undefined && typeof legacy !== "boolean") {
    throw new TypeError(`streamResponse must be a boolean for ${operation}`);
  }
  if (explicit !== undefined && (
    typeof explicit !== "string"
    || !Object.prototype.hasOwnProperty.call(protocols, explicit)
  )) {
    throw new TypeError(`Undeclared response protocol for ${operation}: ${String(explicit)}`);
  }
  const bufferedMedia = descriptor.unsupportedResponseMedia;
  if (explicit === undefined && legacy !== true
    && descriptor.defaultResponseProtocol === null
    && Array.isArray(bufferedMedia) && bufferedMedia.length > 0) {
    return { protocol: "buffered", mediaTypes: bufferedMedia, accept: bufferedMedia.join(", ") };
  }
  let selected = explicit;
  if (selected === undefined && legacy !== undefined) {
    if (legacy) {
      const streams = ["sse", "ndjson"].filter((protocol) => Object.prototype.hasOwnProperty.call(protocols, protocol));
      if (streams.length !== 1) {
        throw new TypeError(`Ambiguous streaming response for ${operation}; set responseProtocol explicitly`);
      }
      selected = streams[0];
    } else {
      selected = "json";
    }
  }
  if (selected === undefined) selected = descriptor.defaultResponseProtocol;
  if (!selected || !Object.prototype.hasOwnProperty.call(protocols, selected)) {
    throw new TypeError(`Select a declared responseProtocol explicitly for ${operation}`);
  }
  if (explicit !== undefined && legacy === true && selected === "json") {
    throw new TypeError(`Conflicting responseProtocol and streamResponse for ${operation}`);
  }
  const mediaTypes = protocols[selected];
  return { protocol: selected, mediaTypes, accept: mediaTypes.join(", ") };
}

async function assertSelectedResponseProtocol(response, selected, method, operation) {
  if (!selected || method === "HEAD" || response.status === 204 || response.status === 205) return;
  const rawContentType = (response.headers && response.headers.get("content-type")) || "";
  const contentType = rawContentType.split(";", 1)[0].trim().toLowerCase();
  if (selected.mediaTypes.includes(contentType)) return;
  if (response.body && typeof response.body.cancel === "function") {
    try { await response.body.cancel(); } catch { /* Preserve the framing error. */ }
  }
  const headers = headerObject(response.headers);
  throw new APIError(`Unexpected response Content-Type for ${operation}; selected ${selected.protocol}`, {
    status: response.status,
    headers,
    operation,
    requestId: headers["x-request-id"] || headers["request-id"],
  });
}

const REQUEST_OPTION_KEYS = new Set([
  "baseURL", "headers", "query", "cookies", "contentType", "timeout",
  "maxRetries", "signal", "idempotencyKey", "rawResponse", "sse",
  "pagination", "maxResponseBytes", "maxStreamEventBytes", "binaryStream",
]);

function _looksLikeRequestOptions(value) {
  return value !== null
    && typeof value === "object"
    && !Array.isArray(value)
    && Object.keys(value).some((key) => REQUEST_OPTION_KEYS.has(key));
}

function _optionalArgumentKind(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number" || typeof value === "bigint") return "number";
  return typeof value;
}

function _matchesOptionalArgument(value, descriptor) {
  const kinds = descriptor && descriptor.kinds;
  return Array.isArray(kinds)
    && (kinds.includes("any") || kinds.includes(_optionalArgumentKind(value)));
}

function _projectOptionalValues(values, descriptors) {
  if (values.length === 0) return descriptors.map(() => undefined);
  if (values.length > descriptors.length) return undefined;
  const earliest = [];
  let target = 0;
  for (const value of values) {
    while (target < descriptors.length
        && !_matchesOptionalArgument(value, descriptors[target])) {
      target += 1;
    }
    if (target >= descriptors.length) return undefined;
    earliest.push(target);
    target += 1;
  }
  const latest = new Array(values.length);
  target = descriptors.length - 1;
  for (let source = values.length - 1; source >= 0; source -= 1) {
    while (target >= 0
        && !_matchesOptionalArgument(values[source], descriptors[target])) {
      target -= 1;
    }
    if (target < 0) return undefined;
    latest[source] = target;
    target -= 1;
  }
  if (earliest.some((value, index) => value !== latest[index])) return undefined;
  const projected = descriptors.map(() => undefined);
  earliest.forEach((destination, source) => {
    projected[destination] = values[source];
  });
  return projected;
}

function _normalizeOptionalArguments(values, descriptors, operation) {
  if (!Array.isArray(values)
      || !Array.isArray(descriptors)
      || values.length !== descriptors.length
      || values.length < 2
      || values.length > 4097) {
    throw new TypeError(`Invalid optional argument projection for ${operation}`);
  }
  const optionIndex = values.length - 1;
  const optionsDescriptor = descriptors[optionIndex];
  if (!optionsDescriptor || optionsDescriptor.requestOptions !== true) {
    throw new TypeError(`Invalid request-options descriptor for ${operation}`);
  }
  const normalized = values.slice();
  const defaultOptions = normalized[optionIndex];
  if (defaultOptions === null
      || typeof defaultOptions !== "object"
      || Array.isArray(defaultOptions)
      || (!_looksLikeRequestOptions(defaultOptions)
          && Object.keys(defaultOptions).length !== 0)) {
    return normalized;
  }
  const supplied = normalized.slice(0, optionIndex)
    .filter((value) => value !== undefined);
  const optionCandidates = supplied
    .map((value, index) => (_looksLikeRequestOptions(value) ? index : -1))
    .filter((index) => index >= 0);
  if (_looksLikeRequestOptions(defaultOptions)) optionCandidates.push(supplied.length);
  if (optionCandidates.length > 1) return normalized;
  let requestOptions = defaultOptions;
  if (optionCandidates.length === 1) {
    const candidate = optionCandidates[0];
    if (candidate < supplied.length - 1) return normalized;
    if (candidate < supplied.length) {
      requestOptions = supplied.pop();
    }
  }
  let projected = _projectOptionalValues(supplied, descriptors.slice(0, optionIndex));
  if (projected === undefined
      && optionCandidates.length === 0
      && supplied.length > 0
      && supplied.at(-1) !== null
      && typeof supplied.at(-1) === "object"
      && !Array.isArray(supplied.at(-1))
      && Object.keys(supplied.at(-1)).length === 0) {
    const emptyOptions = supplied.at(-1);
    projected = _projectOptionalValues(
      supplied.slice(0, -1), descriptors.slice(0, optionIndex),
    );
    if (projected !== undefined) requestOptions = emptyOptions;
  }
  if (projected === undefined) return normalized;
  return [...projected, requestOptions];
}

function _requireParameter(value, name, operation) {
  if (value === undefined) {
    const error = new TypeError(`Missing required parameter '${name}' for ${operation}`);
    error.operation = operation;
    const argument = ownValue(errorHints(operation).parameters, name);
    error.remediation = argumentRemediation(error.message, argument === undefined ? name : argument, operation);
    throw error;
  }
}

function _serializePathParameter(name, value, style = "simple", explode = false, allowReserved = false) {
  if (value === undefined || value === null) return "";
  const encode = (item) => encodePart(item, allowReserved);
  const array = Array.isArray(value) ? value.map(encode) : undefined;
  const object = entriesOf(value).map(([key, item]) => [encode(key), encode(item)]);
  if (style === "label") {
    if (array) return `.${array.join(explode ? "." : ",")}`;
    if (object.length) {
      return `.${object.map(([key, item]) => explode ? `${key}=${item}` : `${key},${item}`).join(explode ? "." : ",")}`;
    }
    return `.${encode(value)}`;
  }
  if (style === "matrix") {
    const encodedName = encodePart(name, allowReserved);
    if (array) {
      return explode
        ? array.map((item) => `;${encodedName}=${item}`).join("")
        : `;${encodedName}=${array.join(",")}`;
    }
    if (object.length) {
      return explode
        ? object.map(([key, item]) => `;${key}=${item}`).join("")
        : `;${encodedName}=${object.flat().join(",")}`;
    }
    return `;${encodedName}=${encode(value)}`;
  }
  if (array) return array.join(",");
  if (object.length) {
    return object.map(([key, item]) => explode ? `${key}=${item}` : `${key},${item}`).join(",");
  }
  return encode(value);
}

function _deepObjectPairs(pairs, name, value, allowReserved, prefix = "") {
  if (value === undefined || value === null) return;
  if (Array.isArray(value)) {
    value.forEach((item, index) => _deepObjectPairs(pairs, name, item, allowReserved, `${prefix}[${index}]`));
  } else if (value && typeof value === "object") {
    for (const [key, item] of Object.entries(value)) {
      _deepObjectPairs(pairs, name, item, allowReserved, `${prefix}[${key}]`);
    }
  } else {
    pairs.push([`${name}${prefix}`, String(value), allowReserved]);
  }
}

function _serializeQueryParameter(pairs, name, value, style = "form", explode = true, allowReserved = false) {
  if (value === undefined || value === null) return;
  if (style === "deepObject") {
    _deepObjectPairs(pairs, name, value, allowReserved);
    return;
  }
  const array = Array.isArray(value) ? value : undefined;
  const object = entriesOf(value);
  if (style === "spaceDelimited" || style === "pipeDelimited") {
    const separator = style === "spaceDelimited" ? " " : "|";
    const flattened = array || (typeof value === "object" ? object.flat() : [value]);
    pairs.push([name, flattened.map(String).join(separator), allowReserved]);
    return;
  }
  if (array) {
    if (explode) array.forEach((item) => pairs.push([name, String(item), allowReserved]));
    else pairs.push([name, array.map(String).join(","), allowReserved]);
    return;
  }
  if (object.length) {
    if (explode) object.forEach(([key, item]) => pairs.push([key, String(item), allowReserved]));
    else pairs.push([name, object.flatMap(([key, item]) => [key, String(item)]).join(","), allowReserved]);
    return;
  }
  pairs.push([name, String(value), allowReserved]);
}

function _serializeSimple(value, explode = false) {
  if (Array.isArray(value)) return value.map(String).join(",");
  const object = entriesOf(value);
  if (object.length) {
    return object.map(([key, item]) => explode ? `${key}=${item}` : `${key},${item}`).join(",");
  }
  return String(value);
}

function _serializeHeaderParameter(value, style = "simple", explode = false, allowReserved = false) {
  if (value === undefined || value === null) return undefined;
  // Header parameters use OpenAPI's simple expansion. `allowReserved` is
  // accepted for descriptor parity, but headers are not URI-percent encoded.
  void allowReserved;
  return style === "simple" ? _serializeSimple(value, explode) : _serializeSimple(value, explode);
}

function _serializeCookieParameter(
  pairs,
  name,
  value,
  style = "form",
  explode = true,
  allowReserved = false,
) {
  if (value === undefined || value === null) return;
  const array = Array.isArray(value) ? value : undefined;
  const object = entriesOf(value);
  if (style !== "form") {
    pairs.push([name, _serializeSimple(value, explode), allowReserved]);
  } else if (array && explode) {
    array.forEach((item) => pairs.push([name, String(item), allowReserved]));
  } else if (array) {
    pairs.push([name, array.map(String).join(","), allowReserved]);
  } else if (object.length && explode) {
    object.forEach(([key, item]) => pairs.push([key, String(item), allowReserved]));
  } else if (object.length) {
    pairs.push([
      name,
      object.flatMap(([key, item]) => [key, String(item)]).join(","),
      allowReserved,
    ]);
  } else {
    pairs.push([name, String(value), allowReserved]);
  }
}

function renderQuery(serialized, query) {
  const pairs = [...(serialized || [])];
  for (const [name, value] of Object.entries(query || {})) {
    _serializeQueryParameter(pairs, name, value, "form", true, false);
  }
  if (!pairs.length) return "";
  return `?${pairs.map(([key, value, allowReserved]) => `${encodePart(key)}=${encodePart(value, allowReserved)}`).join("&")}`;
}

function _jsonWithBigInt(value, seen) {
  // A bigint carries an int64 the contract declared, so it is written as an
  // unquoted JSON number: that is how the peer spells it on the wire, and
  // Number(value) would silently drop every digit above 2^53.
  let current = value;
  if (
    current !== null
    && typeof current === "object"
    && typeof current.toJSON === "function"
  ) {
    current = current.toJSON();
  }
  if (typeof current === "bigint") return current.toString();
  if (current === null || typeof current !== "object") return JSON.stringify(current);
  if (seen.has(current)) throw new TypeError("Converting circular structure to JSON");
  seen.add(current);
  try {
    if (Array.isArray(current)) {
      return `[${current
        .map((item) => {
          const encoded = _jsonWithBigInt(item, seen);
          return encoded === undefined ? "null" : encoded;
        })
        .join(",")}]`;
    }
    const fields = [];
    for (const [name, item] of Object.entries(current)) {
      const encoded = _jsonWithBigInt(item, seen);
      if (encoded !== undefined) fields.push(`${JSON.stringify(name)}:${encoded}`);
    }
    return `{${fields.join(",")}}`;
  } finally {
    seen.delete(current);
  }
}

function encodeJSON(value) {
  // The fast path stays byte-identical to JSON.stringify; only a payload it
  // refuses (a bigint anywhere inside) pays for the manual walk.
  try {
    return JSON.stringify(value);
  } catch (error) {
    if (!(error instanceof TypeError)) throw error;
    return _jsonWithBigInt(value, new Set());
  }
}

function parseJSONPreservingIntegers(text) {
  // JSON.parse rounds an integer past 2^53 before any reviver can see it, so
  // the exact digits are only recoverable from V8's source-text access. Hosts
  // without it keep today's lossy number rather than guessing at the original.
  return JSON.parse(text, function (key, value, context) {
    if (typeof value !== "number" || Number.isSafeInteger(value)) return value;
    const source = context && typeof context.source === "string" ? context.source : "";
    return /^-?\d+$/.test(source) ? BigInt(source) : value;
  });
}

// The part content types a multipart request body declares through its
// `encoding` map, read off the operation's own descriptor.
function multipartEncoding(operation) {
  const descriptor = Object.prototype.hasOwnProperty.call(RESPONSE_DESCRIPTORS, operation)
    ? RESPONSE_DESCRIPTORS[operation]
    : undefined;
  const encoding = descriptor && descriptor.multipartEncoding;
  return encoding && typeof encoding === "object" && !Array.isArray(encoding) ? encoding : {};
}

function isJSONMediaType(mediaType) {
  const normalized = String(mediaType || "").split(";", 1)[0].trim().toLowerCase();
  return normalized === "application/json" || normalized.endsWith("+json");
}

// The most bytes one upload may buffer from a stream, an async iterable or a
// fetch Response when neither `maxUploadBytes` nor `toFile` names a bound. A
// Blob or a byte array is already in memory and is appended as it is.
const DEFAULT_MAX_UPLOAD_BYTES = 104857600;

// What kind of upload source a value is, told apart by duck typing so the
// runtime never loads a Node built-in: a browser bundle has no `stream` or
// `fs` to import, and a Node stream is anything that pipes and emits.
function uploadSourceKind(value) {
  if (value === null || typeof value !== "object") return undefined;
  if (typeof Blob !== "undefined" && value instanceof Blob) return "blob";
  if (
    typeof ArrayBuffer !== "undefined"
    && (value instanceof ArrayBuffer || ArrayBuffer.isView(value))
  ) {
    return "bytes";
  }
  if (typeof Response !== "undefined" && value instanceof Response) return "response";
  if (typeof ReadableStream !== "undefined" && value instanceof ReadableStream) return "web-stream";
  if (typeof value.pipe === "function" && typeof value.on === "function") return "node-stream";
  if (typeof value[Symbol.asyncIterator] === "function") return "async-iterable";
  return undefined;
}

// Buffers one streamed upload into a Blob, refusing it with a RangeError
// (`code: "UPLOAD_TOO_LARGE"`) as soon as it passes `maxBytes`, and keeps the
// name and media type the source itself reports: a file stream's path, a
// Response's URL and Content-Type.
async function readUploadSource(value, kind, maxBytes, label) {
  // Same rule as the client option, so toFile({ maxBytes }) cannot turn null,
  // a negative or a string into the bound it is supposed to enforce.
  if (maxBytes !== undefined && !(typeof maxBytes === "number" && maxBytes > 0)) {
    throw new TypeError(`${label} maxBytes must be a positive number of bytes`);
  }
  const limit = maxBytes === undefined ? DEFAULT_MAX_UPLOAD_BYTES : maxBytes;
  const chunks = [];
  let total = 0;
  const take = (chunk) => {
    let bytes;
    if (typeof chunk === "string") bytes = new TextEncoder().encode(chunk);
    else if (chunk instanceof ArrayBuffer) bytes = new Uint8Array(chunk);
    else if (ArrayBuffer.isView(chunk)) bytes = new Uint8Array(chunk.buffer, chunk.byteOffset, chunk.byteLength);
    else throw new TypeError(`${label} yielded a non-byte chunk (${chunk === null ? "null" : typeof chunk})`);
    total += bytes.byteLength;
    if (total > limit) {
      throw Object.assign(
        new RangeError(`${label} exceeds the ${limit}-byte upload limit (maxUploadBytes)`),
        { code: "UPLOAD_TOO_LARGE", limit },
      );
    }
    chunks.push(bytes);
  };
  const readWebStream = async (stream) => {
    const reader = stream.getReader();
    try {
      while (true) {
        const { done, value: chunk } = await reader.read();
        if (done) break;
        take(chunk);
      }
    } catch (error) {
      try { await reader.cancel(error); } catch { /* The stream may already be errored. */ }
      throw error;
    } finally {
      try { reader.releaseLock(); } catch { /* A cancelled reader may refuse the release. */ }
    }
  };
  const baseName = (path) => {
    const text = String(path);
    return text.slice(Math.max(text.lastIndexOf("/"), text.lastIndexOf("\\")) + 1) || undefined;
  };
  let name;
  let type = "";
  if (kind === "response") {
    type = value.headers.get("content-type") || "";
    try { name = value.url ? baseName(new URL(value.url).pathname) : undefined; } catch { name = undefined; }
    // A response with no body would become a silent empty part, which is the
    // data loss this encoder exists to prevent.
    if (!value.body) throw new TypeError(`${label} received a fetch Response with no body`);
    await readWebStream(value.body);
  } else if (kind === "web-stream") {
    await readWebStream(value);
  } else {
    if (kind === "node-stream" && value.path !== undefined && value.path !== null) name = baseName(value.path);
    if (typeof value[Symbol.asyncIterator] === "function") {
      // Leaving the loop early (a refused chunk) returns the iterator, which
      // destroys a Node stream instead of leaving its file descriptor open.
      for await (const chunk of value) take(chunk);
    } else {
      await new Promise((resolve, reject) => {
        value.on("data", (chunk) => {
          try { take(chunk); } catch (error) {
            if (typeof value.destroy === "function") value.destroy();
            reject(error);
          }
        });
        value.on("end", resolve);
        value.on("error", reject);
      });
    }
  }
  return { blob: new Blob(chunks, type ? { type } : {}), name, type };
}

// Wraps bytes, text, a Blob, a stream, an async iterable or a fetch Response
// as one named upload, so the multipart part carries the filename and media
// type the caller chose. Streamed sources are read within `options.maxBytes`.
async function toFile(value, name, options = {}) {
  if (typeof Blob === "undefined") throw new TypeError("Blob is unavailable in this runtime");
  const kind = typeof value === "string" ? "text" : uploadSourceKind(value);
  if (kind === undefined) {
    throw new TypeError(
      `toFile() cannot read ${value === null ? "null" : typeof value === "object" ? "an object" : `a ${typeof value}`}; `
      + "pass a Blob, File, ArrayBuffer, typed array, string, Node Readable, ReadableStream, "
      + "async iterable of Uint8Array or fetch Response",
    );
  }
  let blob;
  let derivedName;
  let derivedType = "";
  if (kind === "blob") {
    blob = value;
    derivedName = typeof value.name === "string" && value.name ? value.name : undefined;
    derivedType = value.type;
  } else if (kind === "text" || kind === "bytes") {
    blob = new Blob([value]);
  } else {
    const read = await readUploadSource(value, kind, options.maxBytes, "toFile()");
    blob = read.blob;
    derivedName = read.name;
    derivedType = read.type;
  }
  const fileName = name === undefined || name === null ? derivedName || "blob" : String(name);
  const type = options.type === undefined ? derivedType : String(options.type);
  if (typeof File !== "undefined") return new File([blob], fileName, { type });
  // The oldest Node this package declares has Blob but no File: a Blob
  // carrying its own `name` is what the multipart encoder reads the filename
  // from.
  return Object.defineProperty(blob.slice(0, blob.size, type), "name", {
    value: fileName,
    enumerable: true,
  });
}

// `partType` is the content type the contract's `encoding` declares for this
// part, if any. A JSON part travels as a typed Blob so the peer reads
// `Content-Type: application/json` on the part instead of an untyped string.
// `upload` names the operation, the parts the contract declares binary and the
// buffering bound, so a value no byte source describes is refused by field
// before any request rather than sent as its string or JSON form.
async function appendFormValue(form, name, value, partType, upload = {}) {
  if (value === undefined || value === null) return;
  const kind = uploadSourceKind(value);
  const label = `${upload.operation || "multipart request"}: multipart field "${name}"`;
  if (Array.isArray(value)) {
    for (const item of value) await appendFormValue(form, name, item, partType, upload);
  } else if (kind === "blob") {
    if (typeof value.name === "string" && value.name) form.append(name, value, value.name);
    else form.append(name, value);
  } else if (kind === "bytes") {
    if (typeof Blob === "undefined") {
      throw new TypeError("Blob is unavailable for a binary multipart field");
    }
    form.append(name, partType ? new Blob([value], { type: partType }) : new Blob([value]));
  } else if (kind !== undefined) {
    if (typeof Blob === "undefined") {
      throw new TypeError("Blob is unavailable for a binary multipart field");
    }
    const read = await readUploadSource(value, kind, upload.maxBytes, label);
    const blob = partType ? read.blob.slice(0, read.blob.size, partType) : read.blob;
    if (read.name) form.append(name, blob, read.name);
    else form.append(name, blob);
  } else if (
    upload.binary
    && upload.binary.includes(name)
    && !(
      typeof value === "string"
      && partType
      && (partType.toLowerCase().startsWith("text/") || isJSONMediaType(partType))
    )
  ) {
    throw new TypeError(
      `${label} is binary and cannot send ${typeof value === "object" ? "an object" : `a ${typeof value}`}; `
      + "pass a Blob, File, ArrayBuffer, typed array, Node Readable, ReadableStream, "
      + "async iterable of Uint8Array or fetch Response, or wrap the value with toFile()",
    );
  } else if (value && typeof value === "object") {
    const json = encodeJSON(value);
    if (partType && typeof Blob !== "undefined") form.append(name, new Blob([json], { type: partType }));
    else form.append(name, json);
  } else if (partType && isJSONMediaType(partType) && typeof Blob !== "undefined") {
    form.append(name, new Blob([encodeJSON(value)], { type: partType }));
  } else {
    form.append(name, String(value));
  }
}

function resolveServerURL(template, declared, chosen) {
  // A declared `enum` is the contract's own list of reachable deployments, so a
  // value outside it fails here rather than at a host that does not exist.
  let resolved = template;
  for (const [name, variable] of Object.entries(declared)) {
    const selected = chosen && chosen[name] !== undefined
      ? String(chosen[name])
      : variable.default;
    const allowed = variable.enum || [];
    if (allowed.length && !allowed.includes(selected)) {
      throw new TypeError(
        `serverVariables.${name} must be one of ${allowed.join(", ")}`,
      );
    }
    resolved = resolved.split(`{${name}}`).join(selected);
  }
  return resolved;
}

async function encodeBody(value, contentType, headers, encoding = {}, operation = undefined, maxUploadBytes = undefined) {
  if (value === undefined) return undefined;
  const normalized = String(contentType || "application/json").split(";", 1)[0].trim().toLowerCase();
  if (normalized === "multipart/form-data") {
    if (typeof FormData === "undefined") throw new TypeError("FormData is unavailable in this runtime");
    if (value instanceof FormData) return value;
    const form = new FormData();
    const descriptor = operation !== undefined
      && Object.prototype.hasOwnProperty.call(RESPONSE_DESCRIPTORS, operation)
      ? RESPONSE_DESCRIPTORS[operation]
      : undefined;
    const upload = {
      operation,
      binary: descriptor && Array.isArray(descriptor.multipartBinary) ? descriptor.multipartBinary : [],
      maxBytes: maxUploadBytes,
    };
    for (const [name, item] of Object.entries(value || {})) {
      const partType = Object.prototype.hasOwnProperty.call(encoding, name)
        && typeof encoding[name] === "string"
        ? encoding[name]
        : undefined;
      await appendFormValue(form, name, item, partType, upload);
    }
    return form;
  }
  headers["Content-Type"] = contentType || "application/json";
  if (normalized === "application/json" || normalized.endsWith("+json")) return encodeJSON(value);
  if (normalized === "application/x-www-form-urlencoded") {
    const pairs = [];
    for (const [name, item] of Object.entries(value || {})) {
      _serializeQueryParameter(pairs, name, item, "form", true, false);
    }
    return pairs.map(([name, item]) => `${encodePart(name)}=${encodePart(item)}`).join("&");
  }
  if (normalized.startsWith("text/")) return String(value);
  return value;
}

